{
  "name": "@ryanlaiyunzhi/opencode-workflows",
  "version": "0.1.5",
  "description": "OpenCode Workflows —— 基于 OpenCode Plugin SDK 的通用多 Agent 编排框架（OpenCode 版 Claude Code Workflows）",
  "type": "module",
  "license": "MIT",
  "main": "dist/index.js",
  "types": "dist/index.d.ts",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./tui": {
      "types": "./dist/tui.tsx",
      "import": "./dist/tui.tsx"
    }
  },
  "files": [
    "dist/**/*.js",
    "dist/**/*.d.ts",
    "dist/**/*.ts",
    "dist/**/*.tsx",
    "dist/**/*.mjs",
    "README.md",
    "LICENSE",
    "CHANGELOG.md"
  ],
  "scripts": {
    "clean": "node scripts/clean.mjs",
    "build": "node scripts/clean.mjs && tsc -p tsconfig.build.json && node scripts/copy-sources.mjs",
    "prepublishOnly": "npm run build"
  },
  "engines": {
    "opencode": ">=1.15.13",
    "node": ">=18"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": ">=1.15.13"
  },
  "dependencies": {
    "@opentui/core": "^0.3.1",
    "@opentui/solid": "^0.3.1",
    "solid-js": "^1.9.12",
    "typescript": "^5.0.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.15.13",
    "@types/bun": "latest",
    "@types/node": "^20.0.0"
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "workflows",
    "multi-agent",
    "orchestration",
    "claude-code"
  ]
}
